namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    public int DiscountCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * RatePercent(tier) / 100;

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };
}
EOF
python3 - <<'EOF'
p='src/CheckoutPricing.Application/CalculateLoyaltyDiscount.cs'
s=open(p).read()
s=s.replace("""    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query) =>
        new(query.SubtotalCents, 0, query.SubtotalCents, query.LoyaltyTier);""","""    private readonly LoyaltyDiscountPolicy policy = new();

    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discountCents = policy.DiscountCents(query.SubtotalCents, query.LoyaltyTier);
        return new(query.SubtotalCents, discountCents, query.SubtotalCents - discountCents, query.LoyaltyTier);
    }""")
open(p,'w').write(s)
EOF
dotnet test CheckoutPricing.slnx --no-restore --verbosity quiet 2>&1 | grep -E "Failed!|Passed!|error|warn"; git status --short

