namespace CheckoutPricing.UnitTest.Shipping;

public sealed class ShippingScenarioTests
{
    private static int Fee(int payableCents, LoyaltyTier tier, bool express = false) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payableCents, tier, express));

    [Theory]
    [InlineData(4_999, LoyaltyTier.Bronze, 490)]
    [InlineData(5_000, LoyaltyTier.Bronze, 0)]
    [InlineData(4_999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(int payable, LoyaltyTier tier, int fee)
    {
        Assert.Equal(fee, Fee(payable, tier));
    }

    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(LoyaltyTier tier)
    {
        Assert.Equal(0, Fee(1_000, tier));
    }

    [Theory]
    [InlineData(10_000, LoyaltyTier.Bronze, 990)]
    [InlineData(1_000, LoyaltyTier.Gold, 990)]
    [InlineData(1_000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNineNinetyFreeForPlatinumOnly(int payable, LoyaltyTier tier, int fee)
    {
        Assert.Equal(fee, Fee(payable, tier, express: true));
    }
}

using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Checkout;

public sealed class CheckoutQuoteTests
{
    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, "WELCOME5", false, 8_500, 0, 8_500)]
    [InlineData(5_000, LoyaltyTier.Bronze, null, false, 4_750, 490, 5_240)]
    [InlineData(20_000, LoyaltyTier.Platinum, "SUMMER10", true, 16_500, 0, 16_500)]
    [InlineData(2_000, LoyaltyTier.Gold, null, true, 2_000, 990, 2_990)]
    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
        int subtotal, LoyaltyTier tier, string? code, bool express, int payable, int fee, int total)
    {
        var quote = new QuoteCheckout().Handle(new QuoteCheckoutQuery(subtotal, tier, code, express));

        Assert.Equal(new CheckoutQuote(payable, fee, total), quote);
    }
}

